mapper.select:
SELECT u.id AS user_id, u.created_at AS registered_at, a.first_src, a.first_cmp, a.first_ref, a.first_start, a.first_at,
  a.reg_src, a.reg_cmp, a.reg_ref, a.reg_start, a.reg_seen_at, a.created_at
FROM account_user u LEFT JOIN account_attribution a ON a.user_id = u.id
WHERE u.created_at >= #{from} AND u.created_at < #{to}
ORDER BY u.id LIMIT #{limit}
